-- Compact array-driven refresh of 300 draft rows (201-500).
-- Preserves manual edits: only overwrites rows whose content still starts with
-- 'OWNER REVIEW REQUIRED.'.
CREATE OR REPLACE FUNCTION pg_temp.__refresh_owner_kb(
  p_start int, p_category text,
  p_topics text[],
  p_content_tpl text, p_voice_tpl text, p_policy_tpl text, p_sales text,
  p_tag_base text[]
) RETURNS int LANGUAGE plpgsql AS $$
DECLARE
  i int;
  n int;
  topic text;
  content_v text;
  voice_v text;
  policy_v text;
  tag_slug text;
  affected int := 0;
BEGIN
  FOR i IN 1..array_length(p_topics, 1) LOOP
    topic := p_topics[i];
    n := p_start + i - 1;
    content_v := replace(p_content_tpl, '{t}', topic);
    voice_v   := replace(p_voice_tpl,   '{t}', topic);
    policy_v  := replace(p_policy_tpl,  '{t}', topic);
    tag_slug  := lower(regexp_replace(topic, '[^A-Za-z0-9]+', '_', 'g'));
    UPDATE public.business_knowledge
       SET category = p_category,
           title = topic,
           question = 'What should customers know about ' || lower(topic) || '?',
           content = content_v,
           voice_answer = voice_v,
           internal_policy = policy_v,
           sales_guidance = p_sales,
           tags = p_tag_base || ARRAY[tag_slug]::text[],
           review_status = 'draft',
           is_active = false,
           requires_owner_review = true,
           confidence = 'medium',
           updated_at = now()
     WHERE record_number = n
       AND source_type = 'owner_knowledge_project'
       AND review_status = 'draft'
       AND content LIKE 'OWNER REVIEW REQUIRED.%';
    IF FOUND THEN affected := affected + 1; END IF;
  END LOOP;
  RETURN affected;
END $$;

